begin;
select no_plan();
select ok(not has_function_privilege('anon','public.native_admin_record_effect(uuid,jsonb)','execute'),'anonymous cannot record');
select ok(not has_function_privilege('authenticated','public.native_admin_record_effect(uuid,jsonb)','execute'),'authenticated cannot record');
select ok(has_function_privilege('service_role','public.native_admin_record_effect(uuid,jsonb)','execute'),'service RPC only');
select ok(not has_table_privilege('service_role','private.admin_effects','insert'),'service cannot bypass validation');
select ok((select relrowsecurity from pg_class where oid='private.admin_effects'::regclass),'private journal RLS');
insert into public.profiles(id) values('00000000-0000-4000-8000-000000001915'),('00000000-0000-4000-8000-000000001916');
create temporary table effect_fixture(event jsonb);
insert into effect_fixture values(jsonb_build_object('request_id','00000000-0000-4000-8000-000000000005','effect_id','00000000-0000-4000-8000-000000000006','action','set_blocked','effect','clerk_unban','target_hash',repeat('a',64),'outcome','started'));
select throws_ok($$select public.native_admin_record_effect('00000000-0000-4000-8000-000000001915',(select event from effect_fixture))$$,'42501','native_admin_forbidden','non owner rejected');
select * from public.operational_access_set('00000000-0000-4000-8000-000000001915','owner','grant','test:r10-effects','Effects test','test:r10-effects',null);
select is(public.native_admin_record_effect('00000000-0000-4000-8000-000000001915',(select event from effect_fixture)),true,'owner intent committed');
select is(public.native_admin_record_effect('00000000-0000-4000-8000-000000001915',(select event from effect_fixture)),true,'lost RPC ACK idempotent');
select is((select count(*) from private.admin_effects),1::bigint,'no duplicate intent');
select throws_ok($$select public.native_admin_record_effect('00000000-0000-4000-8000-000000001915',(select event||'{"target_hash":"user_private"}' from effect_fixture))$$,'22023','native_admin_invalid','no raw provider identity');
select throws_ok($$select public.native_admin_record_effect('00000000-0000-4000-8000-000000001915',(select event||'{"email":"test@example.invalid"}' from effect_fixture))$$,'22023','native_admin_invalid','closed fields exclude PII');
select throws_ok($$select public.native_admin_record_effect('00000000-0000-4000-8000-000000001915',(select event||'{"effect_id":"bad"}' from effect_fixture))$$,'22023','native_admin_invalid','UUID required');
select throws_ok($$select public.native_admin_record_effect('00000000-0000-4000-8000-000000001915',(select event||'{"effect":"storage_cleanup"}' from effect_fixture))$$,'22023','native_admin_invalid','effect must match action');
select throws_ok($$select public.native_admin_record_effect('00000000-0000-4000-8000-000000001915',(select event||'{"effect_id":"00000000-0000-4000-8000-000000000007","outcome":"succeeded"}' from effect_fixture))$$,'22023','native_admin_invalid','result needs intent');
select throws_ok($$select public.native_admin_record_effect('00000000-0000-4000-8000-000000001915',(select event||jsonb_build_object('target_hash',repeat('b',64),'outcome','succeeded') from effect_fixture))$$,'22023','native_admin_invalid','result bound to exact intent');
select is(public.native_admin_record_effect('00000000-0000-4000-8000-000000001915',(select event||'{"outcome":"succeeded"}' from effect_fixture)),true,'result appended');
select is(public.native_admin_record_effect('00000000-0000-4000-8000-000000001915',(select event||'{"outcome":"succeeded"}' from effect_fixture)),true,'result ACK retry idempotent');
select throws_ok($$select public.native_admin_record_effect('00000000-0000-4000-8000-000000001915',(select event||'{"outcome":"unknown"}' from effect_fixture))$$,'22023','native_admin_invalid','terminal result cannot change');
select is((select count(*) from private.admin_effects),2::bigint,'only intent and one result');
select * from public.operational_access_set('00000000-0000-4000-8000-000000001916','owner','grant','test:r10-effects-other','Other owner','test:r10-effects-other',null);
select throws_ok($$select public.native_admin_record_effect('00000000-0000-4000-8000-000000001916',(select event from effect_fixture))$$,'22023','native_admin_invalid','different actor cannot reuse effect');
update public.operational_access_assignments set granted_at=now()-interval '1 day',expires_at=now()-interval '1 minute' where user_id='00000000-0000-4000-8000-000000001915' and role='owner';
select throws_ok($$select public.native_admin_record_effect('00000000-0000-4000-8000-000000001915',(select event from effect_fixture))$$,'42501','native_admin_forbidden','expired owner cannot append');
select is((select count(*) from private.admin_effects),2::bigint,'abuse leaves evidence unchanged');
select * from finish();
rollback;
